package intersect.oracle;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.eclipse.emf.common.util.URI;import org.eclipse.emf.ecore.*;import org.eclipse.xtext.*;import org.eclipse.xtext.parser.IParser;import org.eclipse.xtext.resource.XtextResourceSet;import org.eclipse.xtext.nodemodel.util.NodeModelUtils;import org.antlr.runtime.*;import org.eclipse.xtext.validation.*;import org.eclipse.xtext.util.CancelIndicator;
public class HiddenScopeRuntime {
 static Map<String,Object> sourceBindings(String filename)throws Exception{Map<String,Object> result=new LinkedHashMap<>();Path root=Path.of(filename).toAbsolutePath().getParent();Set<String> uris=new HashSet<>(),files=new HashSet<>();for(String line:Files.readAllLines(Path.of(filename),StandardCharsets.UTF_8)){String[] p=line.split("\t",-1);if(p.length!=5||!uris.add(p[2])||!files.add(p[4]))throw new IllegalArgumentException("Ambiguous runtime source binding");Path physical=root.resolve(p[4]).normalize();if(!physical.getParent().equals(root)||!HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(physical))).equals(p[3]))throw new IllegalArgumentException("Mismatched runtime source binding");if(p[0].equals("grammar")&&result.put(p[1],fields("uri",p[2],"sha256",p[3]))!=null)throw new IllegalArgumentException("Duplicate runtime grammar binding");}return result;}
 static Object selectedRule(ParserRule rule,String requested,Map<String,Object> sources){var grammar=GrammarUtil.getGrammar(rule);if(rule.eIsProxy()||!requested.equals(rule.getName())||grammar==null||!sources.containsKey(grammar.getName()))throw new IllegalArgumentException("Named entry identity is not an exact bound parser rule");var node=NodeModelUtils.getNode(rule);return fields("requested",requested,"name",rule.getName(),"identity",grammar.getName()+"::"+rule.getName(),"generated_rule_uri",org.eclipse.emf.ecore.util.EcoreUtil.getURI(rule).toString(),"authored_source_for_owner",sources.get(grammar.getName()),"definition_utf16_start",node==null?null:node.getOffset(),"definition_utf16_end",node==null?null:node.getEndOffset());}

 static List<Object> leaves(org.eclipse.xtext.nodemodel.INode node){List<Object> result=new ArrayList<>();if(node!=null)for(var leaf:node.getLeafNodes())result.add(fields("text",leaf.getText(),"hidden",leaf.isHidden(),"utf16_start",leaf.getOffset(),"utf16_end",leaf.getEndOffset(),"syntax_error",leaf.getSyntaxErrorMessage()==null?null:leaf.getSyntaxErrorMessage().getMessage()));return result;}
 static List<Object> modelNodes(EObject root){List<Object> result=new ArrayList<>();if(root==null)return result;List<EObject> all=new ArrayList<>();all.add(root);root.eAllContents().forEachRemaining(all::add);for(var object:all){var node=NodeModelUtils.getNode(object);result.add(fields("class",object.eClass().getEPackage().getNsURI()+"#//"+object.eClass().getName(),"utf16_start",node==null?null:node.getOffset(),"utf16_end",node==null?null:node.getEndOffset(),"total_utf16_start",node==null?null:node.getTotalOffset(),"total_utf16_end",node==null?null:node.getTotalEndOffset()));}return result;}
 static Map<String,Object> fields(Object... values){return TerminalNegationOracle.fields(values);}
 static Object failure(Throwable t){List<Object> chain=new ArrayList<>();for(Throwable c=t;c!=null;c=c.getCause())chain.add(fields("class",c.getClass().getName(),"message",c.getMessage()));return chain;}
 public static void main(String[] args)throws Exception{
  if(args.length!=5)throw new IllegalArgumentException("Expected provider,grammar,text,explicit-entry-or-empty,pinned-source-bindings");var authoredSources=sourceBindings(args[4]);String requestedEntry=args[3];
  for(String name:args[0].split(",")){var p=(EPackage)Class.forName(name).getField("eINSTANCE").get(null);EPackage.Registry.INSTANCE.put(p.getNsURI(),p);}
  var setup=(ISetup)Class.forName(args[1]+"StandaloneSetup").getConstructor().newInstance();var injector=setup.createInjectorAndDoEMFRegistration();String text=new String(Base64.getDecoder().decode(args[2]),StandardCharsets.UTF_8);
  Map<String,Object> result=fields("text",text,"named_entry",requestedEntry.isEmpty()?null:requestedEntry,"lexer",null,"resource",null,"parser",null);
  try{var lexer=injector.getInstance(org.eclipse.xtext.parser.antlr.Lexer.class);lexer.setCharStream(new ANTLRStringStream(text));Map<Integer,String> names=new TreeMap<>();for(var f:lexer.getClass().getFields())if(f.getType()==int.class&&java.lang.reflect.Modifier.isStatic(f.getModifiers())&&(f.getName().startsWith("RULE_")||f.getName().startsWith("T__")))names.put(f.getInt(null),f.getName());List<Object> tokens=new ArrayList<>();boolean complete=false;for(int n=0;n<text.length()+4;n++){var t=(CommonToken)lexer.nextToken();tokens.add(fields("type",t.getType(),"name",t.getType()==Token.EOF?"EOF":names.get(t.getType()),"text",t.getText(),"utf16_start",t.getStartIndex(),"utf16_stop",t.getStopIndex(),"channel",t.getChannel()));if(t.getType()==Token.EOF){complete=true;break;}}result.put("lexer",fields("tokens",tokens,"through_eof",complete,"antlr_syntax_error_count",lexer.getNumberOfSyntaxErrors(),"failure",null));}catch(Throwable t){result.put("lexer",fields("failure",failure(t)));}
  org.eclipse.emf.ecore.resource.Resource resource=null;
  try{var resources=injector.getInstance(XtextResourceSet.class);resource=resources.createResource(URI.createURI("memory:/model.lexicaltest"));resource.load(new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8)),null);List<Object> errors=new ArrayList<>();for(var d:resource.getErrors())errors.add(fields("message",d.getMessage(),"line",d.getLine(),"column",d.getColumn()));List<Object> warnings=new ArrayList<>();for(var d:resource.getWarnings())warnings.add(fields("message",d.getMessage(),"line",d.getLine(),"column",d.getColumn()));var root=resource.getContents().isEmpty()?null:resource.getContents().get(0);List<Object> leaves=new ArrayList<>();if(root!=null){var node=NodeModelUtils.getNode(root);if(node!=null)for(var leaf:node.getLeafNodes())leaves.add(fields("text",leaf.getText(),"hidden",leaf.isHidden(),"utf16_start",leaf.getOffset(),"utf16_end",leaf.getEndOffset(),"syntax_error",leaf.getSyntaxErrorMessage()==null?null:leaf.getSyntaxErrorMessage().getMessage()));}result.put("resource",fields("accepted",root!=null&&errors.isEmpty(),"errors",errors,"warnings",warnings,"resource_contents",resource.getContents().size(),"model",RuntimeOracle.model(root),"leaves",leaves,"all_root_leaves",leaves(((org.eclipse.xtext.resource.XtextResource)resource).getParseResult().getRootNode()),"model_nodes",modelNodes(root),"failure",null));}catch(Throwable t){result.put("resource",fields("accepted",false,"failure",failure(t),"resource_contents",resource==null?null:resource.getContents().size(),"model",resource==null||resource.getContents().isEmpty()?null:RuntimeOracle.model(resource.getContents().get(0))));}
  try{var grammar=injector.getInstance(IGrammarAccess.class).getGrammar();var parser=injector.getInstance(IParser.class);org.eclipse.xtext.parser.IParseResult parsed;if(requestedEntry.isEmpty()){parsed=parser.parse(new StringReader(text));result.put("selected_parser_entry",null);}else{var selected=GrammarUtil.findRuleForName(grammar,requestedEntry);if(!(selected instanceof ParserRule)||!requestedEntry.equals(selected.getName()))throw new IllegalArgumentException("Requested named entry is not an exact ParserRule");var selectedParser=(ParserRule)selected;result.put("selected_parser_entry",selectedRule(selectedParser,requestedEntry,authoredSources));parsed=parser.parse(selectedParser,new StringReader(text));}List<Object> errors=new ArrayList<>();for(var n:parsed.getSyntaxErrors())errors.add(fields("message",n.getSyntaxErrorMessage().getMessage(),"utf16_start",n.getOffset(),"utf16_end",n.getEndOffset()));var root=parsed.getRootASTElement();result.put("parser",fields("accepted",root!=null&&errors.isEmpty(),"errors",errors,"model",RuntimeOracle.model(root),"all_root_leaves",leaves(parsed.getRootNode()),"model_nodes",modelNodes(root),"failure",null));}catch(Throwable t){result.put("parser",fields("accepted",false,"failure",failure(t)));}
  System.out.println(TerminalNegationOracle.json(result));
 }
}
